export const CATALOGUE_LABEL = { min: 1, max: 40 } as const;
export const CATALOGUE_SLUG = { min: 2, max: 40 } as const;
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

const slugField = z
  .string({ error: "Enter a slug." })
  .trim()
  .min(CATALOGUE_SLUG.min, `Use at least ${CATALOGUE_SLUG.min} characters.`)
  .max(CATALOGUE_SLUG.max, `Use ${CATALOGUE_SLUG.max} characters or fewer.`)
  .regex(SLUG, "Use lowercase letters, numbers and dashes.");
const iconField = z
  .string()
  .trim()
  .max(40, "Use 40 characters or fewer.")
  .regex(SLUG, "Choose an icon from the list.")
  .nullable();
const hiddenOnField = z
  .array(z.enum(CONFIG_PLATFORMS, { error: "Choose ios, android or web." }))
  .max(3)
  .refine((a) => new Set(a).size === a.length, "Choose each platform once.");
/** A category or group id: a number sent as a string. */
export const catalogueIdSchema = z.string({ error: "Choose a group." }).regex(/^[1-9]\d{0,4}$/, "Choose a group.");

const groupFields = { label: text(CATALOGUE_LABEL), slug: slugField, icon: iconField, hiddenOn: hiddenOnField };

export const groupCreateSchema = z.strictObject(groupFields);
export const groupUpdateSchema = z.strictObject({ ...groupFields, version: z.number().int().min(1) });
export const categoryCreateSchema = z.strictObject({ ...groupFields, groupId: catalogueIdSchema, enabled: z.boolean().optional() });
export const categoryUpdateSchema = z.strictObject({ ...groupFields, groupId: catalogueIdSchema.optional(), enabled: z.boolean().optional(), version: z.number().int().min(1) });
export type GroupCreateBody = z.output<typeof groupCreateSchema>;
export type GroupUpdateBody = z.output<typeof groupUpdateSchema>;
export type CategoryCreateBody = z.output<typeof categoryCreateSchema>;
export type CategoryUpdateBody = z.output<typeof categoryUpdateSchema>;

/** `POST /ops/category-groups/order { ids }` (every group) and `/categories/order { ids }` (one group's categories). */
export const catalogueOrderSchema = z.strictObject({ ids: z.array(catalogueIdSchema).min(1).max(200) });
export type CatalogueOrderBody = z.output<typeof catalogueOrderSchema>;
